<?php defined( 'ABSPATH' ) || exit; ?>
<div class="wrap"><h1><?php echo esc_html__( 'Lịch sử', 'ecomkit-vuikhoe' ); ?></h1>
<?php if ( empty( $data['batches'] ) ) : ?><p><?php echo esc_html__( 'Chưa có file nào được xử lý.', 'ecomkit-vuikhoe' ); ?> <a href="<?php echo esc_url( add_query_arg( 'page', 'ecomkit-vuikhoe-process', admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html__( 'Xử lý đơn hàng đầu tiên', 'ecomkit-vuikhoe' ); ?></a></p><?php else : ?>
<table class="widefat striped"><thead><tr><th><?php echo esc_html__( 'Batch', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Thời gian', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Tên file', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Nguồn', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Trạng thái', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Tiến độ', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Đơn hợp lệ', 'ecomkit-vuikhoe' ); ?></th><th><?php echo esc_html__( 'Kết quả', 'ecomkit-vuikhoe' ); ?></th></tr></thead><tbody>
<?php foreach ( $data['batches'] as $batch ) : $local_time = wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), strtotime( (string) $batch['created_at'] . ' UTC' ), wp_timezone() ); $metadata = json_decode( (string) ( $batch['source_metadata'] ?? '' ), true ); $state = is_array( $metadata ) ? ( $metadata['auto_pipeline'] ?? null ) : null; $progress = is_array( $state ) ? Ecomkit_Vuikhoe_Auto_Pipeline::progress( $state ) : null; $status = is_array( $progress ) ? (string) $progress['status'] : (string) $batch['status']; $friendly_status = array( 'SUCCESS' => 'Hoàn tất', 'WARNING' => 'Hoàn tất với cảnh báo', 'PROCESSING' => 'Đang xử lý', 'RUNNING' => 'Đang xử lý', 'ERROR' => 'Có lỗi cần xử lý', 'FAILURE' => 'Có lỗi cần xử lý' )[ $status ] ?? 'Đang xử lý'; ?><tr><td><a href="<?php echo esc_url( add_query_arg( array( 'page' => 'ecomkit-vuikhoe-process', 'batch_id' => (int) $batch['id'] ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html( (string) $batch['id'] ); ?></a></td><td><?php echo esc_html( $local_time ); ?></td><td><?php echo esc_html( (string) $batch['source_filename'] ); ?></td><td><?php echo esc_html( (string) $batch['source_type'] ); ?></td><td><?php echo esc_html( $friendly_status ); ?></td><td><?php echo esc_html( is_array( $progress ) ? (string) $progress['percent'] . '%' : '—' ); ?></td><td><?php echo esc_html( (string) $batch['order_count'] ); ?></td><td><a href="<?php echo esc_url( add_query_arg( array( 'page' => 'ecomkit-vuikhoe-results', 'batch_id' => (int) $batch['id'] ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html__( 'Xem kết quả', 'ecomkit-vuikhoe' ); ?></a> · <a href="<?php echo esc_url( add_query_arg( 'page', 'ecomkit-vuikhoe-errors', admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html__( 'Xem lỗi', 'ecomkit-vuikhoe' ); ?></a></td></tr><?php endforeach; ?>
</tbody></table><?php endif; ?></div>
